   314	    if(securityPolicy->asymmetricModule.cryptoModule.encryptionAlgorithm.
   315	        getRemoteKeyLength(securityPolicy, channelContext) > 2048)
   316	        ++paddingBytes;
   317	    size_t padding = (plainTextBlockSize - ((bytesToWrite + signatureSize + paddingBytes) %
   318	                                            plainTextBlockSize));
   319	    *paddingSize = (UA_Byte)(padding & 0xff);
   320	    *extraPaddingSize = (UA_Byte)(padding >> 8);
   321	    return (UA_UInt16)padding;
